#include <bits/stdc++.h>
using namespace std;
#ifndef MODULUS
#define MODULUS 32749
#endif
const int P=MODULUS;
int mod(long long x){x%=P;if(x<0)x+=P;return (int)x;}int mul(int a,int b){return (long long)a*b%P;}int pw(int a,int e){int r=1;while(e){if(e&1)r=mul(r,a);a=mul(a,a);e>>=1;}return r;}
int Cb[32][32],Pow[32][64];int q,D,K;vector<pair<int,int>>mons;
int bc(int a,int b,int r,int v,int sh,int i,int j){if(j>b)return 0;int o=0;for(int z=0;z<=b-j;z++)if(i>=z&&i-z<=a)o=mod(o+(long long)Cb[b][j]*Cb[b-j][z]%P*Pow[v][b-j-z]%P*Pow[sh][z]%P*Cb[a][i-z]%P*Pow[r][a-i+z]);return o;}
struct Basis{vector<vector<int>> row;vector<char>used;int rank=0;Basis():row(K,vector<int>(K)),used(K){}bool add(vector<int>x){for(int c=0;c<K;c++)if(x[c]){if(!used[c]){int inv=pw(x[c],P-2);for(int k=c;k<K;k++)x[k]=mul(x[k],inv);row[c]=move(x);used[c]=1;rank++;return true;}int z=x[c];for(int k=c;k<K;k++)x[k]=mod(x[k]-(long long)z*row[c][k]);}return false;}};
struct Opt{vector<int>m;array<int,9>load{};int z=0;vector<vector<int>>eq;};vector<Opt>opts[6];
void mk(int r,int pos,int rem,vector<int>&m){int k=r/2+1;if(pos==k-1){m[pos]=rem;Opt o;o.m=m;for(int s=0;s<k;s++){int mm=m[s];if(!mm)continue;o.z++;o.load[s]+=mm;o.load[r-s]+=mm;int v=s*(r-s);bool dg=2*s==r;if(dg){for(int w=0;w<2*mm;w++)for(int j=0;2*j<=w;j++){int i=w-2*j;vector<int>x(K);for(int c=0;c<K;c++)x[c]=bc(mons[c].first,mons[c].second,r,v,s,i,j);o.eq.push_back(move(x));}}else{for(int t=0;t<mm;t++)for(int j=0;j<=t;j++){int i=t-j;vector<int>x(K);for(int c=0;c<K;c++)x[c]=bc(mons[c].first,mons[c].second,r,v,0,i,j);o.eq.push_back(move(x));}}}bool bad=0;for(int t=0;t<9;t++)if(o.load[t]>D)bad=1;if(!bad)opts[r-3].push_back(move(o));return;}for(int x=0;x<=rem;x++){m[pos]=x;mk(r,pos+1,rem-x,m);}}
long long nodes=0,linep=0,zp=0,rankp=0,res=0;ofstream out;chrono::steady_clock::time_point start;
void dfs(int ri,array<int,9>L,int z,Basis B,vector<int>&ch){nodes++;if(ri==6){if(z<14){zp++;return;}if(B.rank==K){rankp++;return;}res++;out<<B.rank<<' '<<z;for(int x:ch)out<<' '<<x;out<<'\n';return;}int zmax=0;for(int j=ri;j<6;j++)zmax+=min(q,(j+3)/2+1);if(z+zmax<14){zp++;return;}for(int oi=0;oi<(int)opts[ri].size();oi++){auto&o=opts[ri][oi];auto LL=L;bool bad=0;for(int t=0;t<9;t++){LL[t]+=o.load[t];if(LL[t]>D){bad=1;break;}}if(bad){linep++;continue;}Basis B2=B;for(auto&x:o.eq)B2.add(x);if(B2.rank==K){rankp++;continue;}ch.push_back(oi);dfs(ri+1,LL,z+o.z,move(B2),ch);ch.pop_back();}if(nodes%1000000==0)cerr<<"nodes "<<nodes<<" res "<<res<<" sec "<<chrono::duration<double>(chrono::steady_clock::now()-start).count()<<"\n";}
int main(int argc,char**argv){if(argc!=3){cerr<<"q out\n";return 2;}q=stoi(argv[1]);D=2*q+1;K=(q+1)*(q+2);for(int n=0;n<32;n++){Cb[n][0]=Cb[n][n]=1;for(int k=1;k<n;k++)Cb[n][k]=mod(Cb[n-1][k-1]+Cb[n-1][k]);}for(int a=0;a<32;a++){Pow[a][0]=1;for(int b=1;b<64;b++)Pow[a][b]=mul(Pow[a][b-1],a);}for(int b=q;b>=0;b--)for(int a=D-2*b;a>=0;a--)mons.push_back({a,b});if((int)mons.size()!=K)throw runtime_error("K");cerr<<"q "<<q<<" D "<<D<<" K "<<K<<"\n";for(int r=3;r<=8;r++){vector<int>m(r/2+1);mk(r,0,q,m);cerr<<"row "<<r<<" opts "<<opts[r-3].size()<<"\n";}out.open(argv[2]);start=chrono::steady_clock::now();Basis B;vector<int>ch;dfs(0,{},0,move(B),ch);cerr<<"nodes "<<nodes<<" line "<<linep<<" z "<<zp<<" rank "<<rankp<<" residual "<<res<<" sec "<<chrono::duration<double>(chrono::steady_clock::now()-start).count()<<"\n";}
